import type {
  InferContractRouterInputs,
  InferContractRouterOutputs,
} from "@orpc/contract";
import { z } from "zod";
import { AdmissionLabelSchema } from "../admissions";
import { createContractProcedureBuilder } from "../errors";
import { ImageTypeSchema } from "../images";

// Pagination constants
const DEFAULT_PAGE = 1;
const DEFAULT_PAGE_SIZE = 20;
const MAX_PAGE_SIZE = 100;
const MIN_PAGE = 1;

// Common pagination schemas
const paginationInputSchema = z
  .object({
    page: z.number().int().min(MIN_PAGE).default(DEFAULT_PAGE).optional(),
    pageSize: z
      .number()
      .int()
      .min(1)
      .max(MAX_PAGE_SIZE)
      .default(DEFAULT_PAGE_SIZE)
      .optional(),
  })
  .strict();

const paginationOutputSchema = z
  .object({
    total: z.number().int().nonnegative(),
    page: z.number().int().min(MIN_PAGE),
    pageSize: z.number().int().min(1).max(MAX_PAGE_SIZE),
    totalPages: z.number().int().nonnegative(),
  })
  .strict();

const selectivityTierSchema = z.enum([
  "MOST_SELECTIVE",
  "HIGHLY_SELECTIVE",
  "SELECTIVE",
  "MODERATELY_SELECTIVE",
  "MINIMALLY_SELECTIVE",
  "OPEN_ADMISSION",
]);

const sizeBucketSchema = z.enum([
  "VERY_SMALL",
  "SMALL",
  "MEDIUM",
  "LARGE",
  "VERY_LARGE",
]);

const prestigeTierSchema = z.enum([
  "ELITE",
  "HIGHLY_RANKED",
  "WELL_REGARDED",
  "REGIONAL",
  "STANDARD",
]);

// University schemas
const universityListItemSchema = z
  .object({
    unitid: z.number().int().nonnegative(),
    name: z.string(),
    state: z.string().length(2),
    city: z.string().nullable(),
    isPublic: z.boolean(),
    latestYear: z.number().int().nullable(),
    websiteUrl: z.string().nullable(),
    admitRateOverall: z.number().min(0).max(1).nullable(),
    avgNetPrice: z.number().nullable(),
    medianEarnings10yr: z.number().nullable(),
    completionRate: z.number().min(0).max(1).nullable(),
    retentionRate: z.number().min(0).max(1).nullable(),
    studentSize: z.number().int().nullable(),
    selectivityTier: selectivityTierSchema.nullable(),
    sizeBucket: sizeBucketSchema.nullable(),
    prestigeTier: prestigeTierSchema.nullable(),
    popularityScore: z.number().nullable(),
    featuredImageUrl: z.string().url().nullable(),
    featuredImageAlt: z.string().nullable(),
    createdAt: z.string(), // ISO date string
    updatedAt: z.string(), // ISO date string
  })
  .strict();

export const UNIVERSITY_IMAGE_VARIANT_NAMES = [
  "logo_square_sm",
  "logo_square_lg",
  "logo_icon",
  "banner_hero",
  "banner_hero_2x",
  "banner_mobile",
  "gallery_md",
  "gallery_sm",
] as const;

const universityImageVariantUrlsSchema = z
  .object(
    Object.fromEntries(
      UNIVERSITY_IMAGE_VARIANT_NAMES.map((name) => [
        name,
        z.string().url().optional(),
      ]),
    ),
  )
  .strict();

const universityMediaImageSchema = z
  .object({
    id: z.string(),
    imageType: ImageTypeSchema.nullable(),
    sortOrder: z.number().int().nonnegative(),
    isFeatured: z.boolean(),
    label: z.string().nullable(),
    altText: z.string().nullable(),
    caption: z.string().nullable(),
    metadata: z.record(z.string(), z.string()).nullable(),
    defaultDeliveryUrl: z.string().url(),
    variantUrls: universityImageVariantUrlsSchema,
    width: z.number().int().positive().nullable(),
    height: z.number().int().positive().nullable(),
  })
  .strict();

const addressTypeSchema = z.enum(["HOME", "MAILING", "CAMPUS", "OTHER"]);

const universityAddressSchema = z
  .object({
    id: z.string(),
    type: addressTypeSchema,
    street1: z.string().nullable(),
    street2: z.string().nullable(),
    city: z.string().nullable(),
    state: z.string().nullable(),
    postalCode: z.string().nullable(),
    country: z.string().nullable(),
    lat: z.number().nullable(),
    lng: z.number().nullable(),
    createdAt: z.string(),
    updatedAt: z.string(),
  })
  .strict();

const universityMediaSchema = z
  .object({
    logos: z.array(universityMediaImageSchema),
    banners: z.array(universityMediaImageSchema),
    gallery: z.array(universityMediaImageSchema),
    other: z.array(universityMediaImageSchema),
  })
  .strict();

const universityAdmissionResultSchema = z
  .object({
    id: z.string(),
    runId: z.string(),
    label: AdmissionLabelSchema,
    probability: z.number(),
    score10: z.number(),
    breakdown: z.unknown(),
    baselineLogit: z.number().nullable(),
    createdAt: z.string(),
  })
  .strict();

const universityRoiSchema = z
  .object({
    dataYear: z.string(),
    degreeLevel: z.string(),
    roi10yr: z.number().nullable(),
    roi15yr: z.number().nullable(),
    roi20yr: z.number().nullable(),
    roi30yr: z.number().nullable(),
    roi40yr: z.number().nullable(),
  })
  .strict();

const universityDetailsSchema = z
  .object({
    unitid: z.number().int().nonnegative(),
    name: z.string(),
    state: z.string().length(2),
    isPublic: z.boolean(),
    latestYear: z.number().int().nullable(),
    city: z.string().nullable(),
    address: z.string().nullable().optional(),
    zip: z.string().nullable().optional(),
    lat: z.number().nullable().optional(),
    lng: z.number().nullable().optional(),
    websiteUrl: z.string().nullable(),
    priceCalculatorUrl: z.string().nullable(),
    avgNetPrice: z.number().nullable(),
    medianEarnings10yr: z.number().nullable(),
    completionRate: z.number().min(0).max(1).nullable(),
    retentionRate: z.number().min(0).max(1).nullable(),
    studentSize: z.number().int().nullable(),
    selectivityTier: selectivityTierSchema.nullable(),
    sizeBucket: sizeBucketSchema.nullable(),
    prestigeTier: prestigeTierSchema.nullable(),
    popularityScore: z.number().nullable(),
    isFlagship: z.boolean(),
    minorityServingHbcu: z.boolean(),
    minorityServingHispanic: z.boolean(),
    minorityServingTribal: z.boolean(),
    minorityServingAapi: z.boolean(),
    carnegieBasic: z.number().int().nullable(),
    carnegieUndergrad: z.number().int().nullable(),
    carnegieSizeSetting: z.number().int().nullable(),
    locale: z.number().int().nullable(),
    regionId: z.number().int().nullable(),
    createdAt: z.string(),
    updatedAt: z.string(),
    profile: z.unknown(), // University profile JSON
    schemaVersion: z.string(),
    campusAddress: universityAddressSchema.nullable(),
    addresses: z.array(universityAddressSchema),
    aliases: z
      .array(
        z.object({
          alias: z.string(),
          aliasType: z.string().nullable(),
          isPrimary: z.boolean(),
        }),
      )
      .default([]),
    roi: universityRoiSchema.nullable(),
    projection: z
      .object({
        id: z.string(),
        year: z.number().int().nullable(),
        admitRateOverall: z.number().min(0).max(1).nullable(),
        admitRateInState: z.number().min(0).max(1).nullable(),
        admitRateOutOfState: z.number().min(0).max(1).nullable(),
        satComposite25: z.number().int().nullable(),
        satComposite75: z.number().int().nullable(),
        satEbrw25: z.number().int().nullable(),
        satEbrw75: z.number().int().nullable(),
        satMath25: z.number().int().nullable(),
        satMath75: z.number().int().nullable(),
        actComposite25: z.number().int().nullable(),
        actComposite75: z.number().int().nullable(),
        actEnglish25: z.number().int().nullable(),
        actEnglish75: z.number().int().nullable(),
        actMath25: z.number().int().nullable(),
        actMath75: z.number().int().nullable(),
        avgAdmitGpa4: z.number().nullable(),
        testPolicy: z
          .enum(["REQUIRED", "OPTIONAL", "NOT_CONSIDERED"])
          .nullable(),
        c7Rigor: z.string().nullable(),
        c7Gpa: z.string().nullable(),
        c7Tests: z.string().nullable(),
        c7Essay: z.string().nullable(),
        c7Recommendations: z.string().nullable(),
        c7Extracurriculars: z.string().nullable(),
        dataVersion: z.string().nullable(),
      })
      .nullable(),
    admissionResults: z.array(universityAdmissionResultSchema),
    statsCount: z.number().int().nonnegative(),
    media: universityMediaSchema,
  })
  .strict();

const listUniversitiesInputSchema = paginationInputSchema.extend({
  search: z.string().min(1).optional(),
  state: z.string().length(2).optional(),
  isPublic: z.boolean().optional(),
  sortBy: z
    .enum(["name", "state", "admitRateOverall", "createdAt", "updatedAt"])
    .default("name")
    .optional(),
  sortOrder: z.enum(["asc", "desc"]).default("asc").optional(),
});

const listUniversitiesOutputSchema = z
  .object({
    items: z.array(universityListItemSchema),
    pagination: paginationOutputSchema,
  })
  .strict();

// Contract definition
const contractProcedure = createContractProcedureBuilder();

const syncFromScorecardInputSchema = z
  .object({
    limit: z.number().int().positive().optional(),
    dryRun: z.boolean().optional(),
  })
  .strict()
  .optional();

const syncFromScorecardOutputSchema = z
  .object({
    ingestId: z.string().uuid(),
    message: z.string(),
    status: z.enum(["initiated", "failed"]),
  })
  .strict();

const syncGooglePhotosInputSchema = z
  .object({
    unitid: z.number().int().nonnegative(),
  })
  .strict();

const syncGooglePhotosOutputSchema = z
  .object({
    syncId: z.string().uuid(),
    message: z.string(),
    status: z.enum(["queued", "failed"]),
  })
  .strict();

const baseUniversitiesContract = {
  list: contractProcedure
    .input(listUniversitiesInputSchema)
    .output(listUniversitiesOutputSchema),
  get: contractProcedure
    .input(
      z.object({
        unitid: z.number().int().nonnegative(),
      }),
    )
    .output(universityDetailsSchema),
};

export const universitiesContract = {
  ...baseUniversitiesContract,
  syncFromScorecard: contractProcedure
    .input(syncFromScorecardInputSchema)
    .output(syncFromScorecardOutputSchema),
  syncGooglePhotos: contractProcedure
    .input(syncGooglePhotosInputSchema)
    .output(syncGooglePhotosOutputSchema),
};

export const studentUniversitiesContract = baseUniversitiesContract;

export type UniversitiesContract = typeof universitiesContract;
export type StudentUniversitiesContract = typeof studentUniversitiesContract;
export type UniversitiesContractInputs =
  InferContractRouterInputs<UniversitiesContract>;
export type UniversitiesContractOutputs =
  InferContractRouterOutputs<UniversitiesContract>;
export type StudentUniversitiesContractInputs =
  InferContractRouterInputs<StudentUniversitiesContract>;
export type StudentUniversitiesContractOutputs =
  InferContractRouterOutputs<StudentUniversitiesContract>;
export type UniversityImageVariantName =
  (typeof UNIVERSITY_IMAGE_VARIANT_NAMES)[number];
export type UniversityMediaImage = z.infer<typeof universityMediaImageSchema>;
export type UniversityMedia = z.infer<typeof universityMediaSchema>;
export type UniversityAddress = z.infer<typeof universityAddressSchema>;
export type UniversityAdmissionResult = z.infer<
  typeof universityAdmissionResultSchema
>;
export type UniversityROI = z.infer<typeof universityRoiSchema>;

// Type exports for easier usage
export type ListUniversitiesInput = UniversitiesContractInputs["list"];
export type ListUniversitiesOutput = UniversitiesContractOutputs["list"];
export type GetUniversityInput = UniversitiesContractInputs["get"];
export type GetUniversityOutput = UniversitiesContractOutputs["get"];
export type SyncFromScorecardInput =
  UniversitiesContractInputs["syncFromScorecard"];
export type SyncFromScorecardOutput =
  UniversitiesContractOutputs["syncFromScorecard"];
export type SyncGooglePhotosInput =
  UniversitiesContractInputs["syncGooglePhotos"];
export type SyncGooglePhotosOutput =
  UniversitiesContractOutputs["syncGooglePhotos"];

export type {
  GooglePhotoSyncBatchCompletedPayload,
  GooglePhotoSyncBatchRequestPayload,
  GooglePhotoSyncCompletedPayload,
  GooglePhotoSyncRequestPayload,
  UnsplashPhotoSyncBatchCompletedPayload,
  UnsplashPhotoSyncBatchRequestPayload,
  UnsplashPhotoSyncCompletedPayload,
  UnsplashPhotoSyncRequestPayload,
} from "./photos";
export {
  googlePhotoSyncBatchCompletedPayloadSchema,
  googlePhotoSyncBatchRequestPayloadSchema,
  googlePhotoSyncCompletedPayloadSchema,
  googlePhotoSyncRequestPayloadSchema,
  unsplashPhotoSyncBatchCompletedPayloadSchema,
  unsplashPhotoSyncBatchRequestPayloadSchema,
  unsplashPhotoSyncCompletedPayloadSchema,
  unsplashPhotoSyncRequestPayloadSchema,
} from "./photos";
